                    $query .= ' and ( "access_user"."name" like :search)';
                    $params[] = new SqlParam(name:'search', value: '%'. $filterSearch . '%', type: SqlParam::STR);
                }
                if ($filter->isTenantAndNameAssigned()) {
                    $filterTenantAndName = $filter->tenantAndName();
                    $tenantAndNameParts = [];
